using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  bool RelayMode;string RelaySelfTest;
  const string RelayApprovalNotice="CODEX_RELAY 当前仅支持定向对话与纯文字任务；正式审批未接入。原离线 SIM 入口保留，接力回复不等于正式审批或实施授权。";
  void ReadRelayMode(){var cfg=Json.Codec.DeserializeObject(File.ReadAllText(Config));RelayMode=Json.Str(cfg,"mode")=="CODEX_RELAY";if(RelayMode&&Json.Str(cfg,"profileId")!="codex-relay-001")throw new InvalidOperationException("接力 profileId 不匹配。");}
  void ValidateRelayHealth(object health){ValidateHybridHealth(health);if(RelayMode&&!String.IsNullOrEmpty(SelfTest))throw new InvalidOperationException("SIM 自测不能用于接力 profile。");if(!String.IsNullOrEmpty(RelaySelfTest)){string testRoot=Path.GetFullPath(Path.Combine(Root,"test-output"))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(Config).StartsWith(testRoot,StringComparison.OrdinalIgnoreCase)||!String.Equals(Path.GetDirectoryName(Path.GetFullPath(RelaySelfTest)),Path.GetDirectoryName(Path.GetFullPath(Config)),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("接力原生自测只允许 test-output 下的虚构 Host 配置与同目录证据。");}if(RelayMode&&(Json.Str(health,"mode")!="CODEX_RELAY"||Json.Str(health,"profileId")!="codex-relay-001"||Json.Bool(health,"independentRuntime")||Json.Bool(health,"formalReviewAvailable")))throw new InvalidOperationException("接力 Host 身份或能力声明不匹配。");}
  bool ParticipantCanQueue(object p){if(HybridMode)return Json.Str(p,"kind")=="hybrid_native"&&Json.Bool(p,"queueAvailable");return RelayMode?Json.Str(p,"id")=="chatgpt"&&Json.Str(p,"kind")=="codex_relay"&&Json.Str(p,"status")=="relay_ready":Json.Str(p,"status")=="simulated_ready";}
  string RelayParticipantLabel(object p){string s=Json.Str(p,"status");if(s=="inactive")return "未参与";if(Json.Str(p,"id")!="chatgpt")return "未接入";var control=Json.Get(State,"controlSummary");if(Json.Bool(control,"paused"))return "接力投递全局暂停";if(Json.Bool(Json.Get(control,"rolePaused"),"chatgpt"))return "ChatGPT 接力投递暂停";if(s=="relay_ready")return "接力队列可收件 · 原会话收件未确认";if(s=="paused")return "接力投递暂停";return "接力未就绪";}
  string DisplayStateName(string s){if(HybridMode)return HybridStateName(s);if(!RelayMode)return StateName(s);switch((s??"").ToLowerInvariant()){case "queued":return "等待 Codex 接力 · 未确认原会话收件";case "sending":case "leased":return "接力处理中 · 未确认原会话收件";case "submitted":return "接力已提交 · 原会话收件尚未确认";case "unknown":return "UNKNOWN · 结果未知，不自动重发";case "received":return "已收到原会话回复";case "expired":return "已过期 · 未完成";default:return StateName(s);}}
  void SetupRelayPresentation(){if(!RelayMode||!UxMode)return;Win.Title="TriReviewBridge · ChatGPT原会话·Codex接力";C<TextBlock>("ModeBadge").Text="Codex 接力";C<TextBlock>("ModeWindowNote").Text="关闭窗口不会停止本机队列。Codex 接力按需运行，尚未实现原 ChatGPT 独立常驻。";C<TextBlock>("ModeBoundaryText").Text="ChatGPT原会话·Codex接力。Worker 离线时请求保留排队；提交不等于原会话收件。Hermes / DSH 未接入；UNKNOWN 不自动重发。";C<TextBlock>("RecipientHint").Text="只向绑定的原 ChatGPT 会话排队；等待 Worker 不代表消息丢失。";Composer.ToolTip="支持定向对话与纯文字任务；Ctrl+Enter 发送。正式审批尚未接入。";foreach(string id in new[]{"BindButton","PauseBindingButton","ParticipantsButton","NewProjectButton","NewWorkspaceButton","NewReviewButton","MessageReviewButton","ReviseButton","AuthorizeButton","CrossButton","ReviewRecordButton","ForwardButton","AttachKnowledgeButton","KnowledgeButton","ProjectSettingsButton","ObservationButton","StopBackendButton"}){var b=C<Button>(id);if(b!=null){b.IsEnabled=false;b.ToolTip=RelayApprovalNotice;}}Discussion.IsEnabled=false;((TabItem)MainTabs().Items[1]).Header="纯文字任务";((TabItem)MainTabs().Items[2]).Visibility=Visibility.Collapsed;((TabItem)MainTabs().Items[3]).Visibility=Visibility.Collapsed;Note("ChatGPT原会话·Codex接力 · 正在核对本机 Host。非独立常驻。");}
  void AppendRelayContext(List<string> issues){var worker=Json.Get(State,"worker");string last=Json.Str(worker,"lastSeenAt");C<TextBlock>("ContextParticipantsText").Text+="\nWorker："+(String.IsNullOrEmpty(last)?"尚无活动记录 · 请求等待接力":"最近活动 "+LocalTime(last)+"（非原会话在线认证）");C<TextBlock>("ContextMaterialText").Text="本轮仅文字；附件与原会话字节交付未接入。";C<TextBlock>("ContextReviewText").Text=RelayApprovalNotice;issues.Add(String.IsNullOrEmpty(last)?"Worker 尚无活动记录，消息排队等待接力":"Codex 接力按需运行，原 ChatGPT 独立常驻尚未完成");if(Json.Arr(Json.Get(State,"deliveries")).Any(d=>Json.Bool(d,"cancelRequested")&&Json.Str(d,"state")=="unknown"))issues.Add("在途取消已记录；结果仍 UNKNOWN，等待核对，不再发送");}
  async Task RunRelaySelfTest(){if(!RelayMode)throw new Exception("Relay test requires isolated CODEX_RELAY Host");if(!Chosen().SequenceEqual(new[]{"chatgpt"})||!Receivers.Items.Cast<ListBoxItem>().Single().IsEnabled)throw new Exception("Offline relay worker disabled queue admission");if(!Win.Title.Contains("ChatGPT原会话·Codex接力")||C<Button>("NewReviewButton").IsEnabled||C<Button>("BindButton").IsEnabled)throw new Exception("Relay identity or protected controls missing");Composer.Text="虚构接力界面测试：请只回复三种虚构颜色。";await Send();await RefreshWorkspace();var delivery=Json.Arr(Json.Get(State,"deliveries")).Last();if(Json.Str(delivery,"state")!="queued")throw new Exception("Offline worker did not preserve queued state");var user=Json.Arr(Json.Get(State,"messages")).Last(m=>Json.Str(m,"author")=="user");string original=Json.Str(delivery,"state");try{Json.Obj(delivery)["state"]="submitted";if(!UxDeliverySummary(user,new[]{delivery}).Contains("收件尚未确认"))throw new Exception("Submitted was displayed as confirmed receipt");Json.Obj(delivery)["state"]="unknown";if(!UxDeliverySummary(user,new[]{delivery}).Contains("结果未知"))throw new Exception("UNKNOWN displayed as success");RefreshUxContext();if(!C<TextBlock>("AttentionText").Text.Contains("不自动重发"))throw new Exception("UNKNOWN warning missing");}finally{Json.Obj(delivery)["state"]=original;}bool reviewLocked=false;try{await NewReview("虚构审批",null);}catch(InvalidOperationException){reviewLocked=true;}if(!reviewLocked)throw new Exception("Formal approval was available");Composer.Text="让ChatGPT负责整理虚构颜色说明，只输出文字。";await Send();await RefreshWorkspace();if(!Json.Arr(Json.Get(State,"items")).Any(i=>Json.Str(i,"scope")=="text_only_task"))throw new Exception("Main composer text task was not created");File.WriteAllText(RelaySelfTest,Json.Show(Json.D("passed",true,"offlineWorkerQueueSelectable",true,"chatQueued",true,"mainComposerTextTaskQueued",true,"submittedNotReceipt",true,"unknownNotSuccessOrResent",true,"formalReviewUnavailable",true,"simulationBindingsDisabled",true,"identity","ChatGPT原会话·Codex接力","independentRuntime",false,"realSessionOperations",0)),System.Text.Encoding.UTF8);Win.Close();}
 }
}
